# AI: below section was generated by an AI
# Build an upstream release with the local BC250 usermod; never flash a device.
[CmdletBinding()]
param(
  [ValidatePattern('^v[0-9]+\.[0-9]+\.[0-9]+$')][string]$Tag,
  [switch]$Latest,
  [switch]$PrepareOnly,
  [switch]$WifiCore1,
  [switch]$NoNetworkDebug
)
$ErrorActionPreference = 'Stop'
Set-StrictMode -Version Latest
$repo = Split-Path $PSScriptRoot -Parent
$utf8 = New-Object System.Text.UTF8Encoding($false)

# Native commands do not throw on failure in Windows PowerShell 5.1.
function Invoke-Checked([string]$Exe, [string[]]$Arguments) {
  & $Exe @Arguments
  if ($LASTEXITCODE -ne 0) { throw "$Exe failed with exit code $LASTEXITCODE" }
}

if ($Latest -and $Tag) { throw 'Choose either -Latest or -Tag.' }
$pin = Get-Content (Join-Path $PSScriptRoot 'bc250-release.json') -Raw | ConvertFrom-Json
$usePin = !$Latest -and !$Tag
if ($Latest) {
  $release = Invoke-RestMethod 'https://api.github.com/repos/wled/WLED/releases/latest'
  if ($release.draft -or $release.prerelease) { throw 'GitHub returned a non-stable release.' }
  $Tag = $release.tag_name
} elseif (!$Tag) { $Tag = $pin.tag }
if ($Tag -notmatch '^v[0-9]+\.[0-9]+\.[0-9]+$') { throw "Unsupported release tag: $Tag" }

Push-Location $repo
try {
  & git show-ref --verify --quiet "refs/tags/$Tag"
  $hasTag = $LASTEXITCODE -eq 0
  $commit = $null
  if ($hasTag) {
    $commit = & git rev-parse --verify "refs/tags/${Tag}^{commit}"
    if ($LASTEXITCODE -ne 0) { throw 'Cannot resolve local release tag.' }
  }
  if (!$hasTag -or $Latest) {
    Invoke-Checked git @('fetch', '--no-tags', 'https://github.com/wled/WLED.git', "refs/tags/$Tag")
    $commit = & git rev-parse 'FETCH_HEAD^{commit}'
    if ($LASTEXITCODE -ne 0) { throw 'Cannot resolve fetched release.' }
  }
  $commit = "$commit".Trim()
  if ($usePin -and $commit -ne $pin.commit) { throw 'Pinned release commit does not match; refusing to build.' }
  $runName = "$Tag-$(Get-Date -Format 'yyyyMMdd-HHmmss')-$([guid]::NewGuid().ToString('N').Substring(0,8))"
  $run = Join-Path $repo "build_output/bc250/$runName"
  $source = Join-Path $run 'source'
  New-Item -ItemType Directory -Path $source -Force | Out-Null
  $archive = Join-Path $run 'upstream.zip'
  Invoke-Checked git @('archive', '--format=zip', "--output=$archive", $commit)
  Expand-Archive -LiteralPath $archive -DestinationPath $source

  # Keep hardware logic in one place. Only build inputs are copied, not diagrams.
  $mod = Join-Path $source 'usermods/BC250Power'
  New-Item -ItemType Directory -Path $mod -Force | Out-Null
  $hashes = [ordered]@{}
  foreach ($name in @('BC250Power.cpp', 'ControllerLearning.h', 'ControllerScanner.h', 'library.json')) {
    $inputFile = Join-Path $repo "usermods/BC250Power/$name"
    Copy-Item -LiteralPath $inputFile -Destination $mod
    $hashes[$name] = (Get-FileHash -LiteralPath $inputFile -Algorithm SHA256).Hash
  }
  $config = Join-Path $PSScriptRoot 'bc250-platformio.ini'
  Copy-Item -LiteralPath $config -Destination (Join-Path $source 'platformio_override.ini')
  $hashes['platformio_override.ini'] = (Get-FileHash $config -Algorithm SHA256).Hash

  # Keep serial diagnostics while excluding the network debug transport entirely.
  if ($NoNetworkDebug) {
    $overridePath = Join-Path $source 'platformio_override.ini'
    $override = [IO.File]::ReadAllText($overridePath)
    $hostFlag = '(?m)^\s*-D WLED_DEBUG_HOST=[^\r\n]*\r?\n'
    if ([regex]::Matches($override, $hostFlag).Count -ne 1) { throw 'Network debug flag changed; review before building.' }
    [IO.File]::WriteAllText($overridePath, [regex]::Replace($override, $hostFlag, ''), $utf8)
    $hashes['platformio_override.ini'] = (Get-FileHash $overridePath).Hash
  }

  # Experimental opt-in: patch a private framework copy, never the installed SDK.
  if ($WifiCore1) {
    $frameworkCopy = Join-Path $run 'framework-wifi-core1'
    & (Join-Path $PSScriptRoot 'prepare-bc250-wifi-core1.ps1') -Destination $frameworkCopy
    $overridePath = Join-Path $source 'platformio_override.ini'
    $frameworkUri = 'file://' + $frameworkCopy.Replace('\', '/')
    Add-Content $overridePath "`nplatform_packages = framework-arduinoespressif32 @ $frameworkUri"
    # The diagnostic flag belongs to the existing multiline build_flags value.
    $override = [IO.File]::ReadAllText($overridePath)
    $flagAnchor = 'build_flags = ${env:esp32dev.build_flags}'
    if (!$override.Contains($flagAnchor)) { throw 'Build flag anchor changed.' }
    $override = $override.Replace($flagAnchor, $flagAnchor + "`n  -D BC250_CORE_DIAGNOSTICS")
    [IO.File]::WriteAllText($overridePath, $override, $utf8)
    $hashes['platformio_override.ini'] = (Get-FileHash $overridePath).Hash
    $hashes['framework-core-manifest'] = (Get-FileHash (Join-Path $frameworkCopy 'bc250-core-manifest.json')).Hash
  }

  # Fail closed if upstream consumes our ID or changes the integration anchors.
  $constFile = Join-Path $source 'wled00/const.h'
  $constants = [IO.File]::ReadAllText($constFile)
  if ($constants -match '(?m)^\s*#define\s+USERMOD_ID_\w+\s+59\b' -or $constants.Contains('USERMOD_ID_BC250_POWER')) {
    throw 'Usermod ID 59 is already assigned; integration needs review.'
  }
  $anchor = '(?m)^#define USERMOD_ID_USER_FX[^\r\n]*'
  if ([regex]::Matches($constants, $anchor).Count -ne 1) { throw 'Usermod ID anchor changed.' }
  $constants = [regex]::Replace($constants, $anchor, '$0' + "`n#define USERMOD_ID_BC250_POWER 59 // Personal BC250 controller")
  [IO.File]::WriteAllText($constFile, $constants, $utf8)
  $pinFile = Join-Path $source 'wled00/pin_manager.h'
  $pins = [IO.File]::ReadAllText($pinFile)
  $anchor = '(enum struct PinOwner : uint8_t\s*\{)'
  if ([regex]::Matches($pins, $anchor).Count -ne 1 -or $pins.Contains('UM_BC250Power')) { throw 'Pin-owner integration changed.' }
  $pins = [regex]::Replace($pins, $anchor, '$1' + "`n  UM_BC250Power = USERMOD_ID_BC250_POWER,")
  [IO.File]::WriteAllText($pinFile, $pins, $utf8)

  # Upstream's 500/850 ms age assertion fails on slow Windows builds. Check that
  # regeneration occurred after its command started, without a speed limit.
  # This changes tests in the export only, never firmware or upstream sources.
  $testFile = Join-Path $source 'tools/cdata-test.js'
  $testSource = [IO.File]::ReadAllText($testFile)
  $oldAssertion = if ($testSource.Contains("Date.now() - modifiedTime < 500")) { "Date.now() - modifiedTime < 500" } else { "Date.now() - modifiedTime < 850" }
  $oldExec = 'const execPromise = util.promisify(child_process.exec);'
  $testTimingFix = $false
  if ($testSource.Contains($oldAssertion)) {
    if (!$testSource.Contains($oldExec)) { throw 'Upstream test timing workaround needs review.' }
    $testSource = $testSource.Replace($oldExec, @'
// AI: Measure file regeneration relative to command start, not command speed.
const nativeExecPromise = util.promisify(child_process.exec);
let lastCommandStarted = 0;
const execPromise = (...args) => {
  lastCommandStarted = Date.now();
  return nativeExecPromise(...args);
};
'@).Replace($oldAssertion, 'modifiedTime >= lastCommandStarted')
    [IO.File]::WriteAllText($testFile, $testSource, $utf8)
    $testTimingFix = $true
  }

  $manifest = [ordered]@{
    tag = $Tag; upstreamCommit = $commit; inputs = $hashes
    createdUtc = [DateTime]::UtcNow.ToString('o'); status = 'prepared'
    environment = 'bc250_power'; deployPerformed = $false
    wifiCore1Experiment = [bool]$WifiCore1
    networkDebugDisabled = [bool]$NoNetworkDebug
    webTestTimingCorrection = $testTimingFix
  }
  $manifestPath = Join-Path $run 'manifest.json'
  $manifest | ConvertTo-Json -Depth 5 | Set-Content -Encoding UTF8 $manifestPath
  Write-Host "Prepared $Tag ($commit) in $source"
  if ($PrepareOnly) { return }

  $pio = Join-Path $env:USERPROFILE '.platformio/penv/Scripts/platformio.exe'
  if (!(Test-Path $pio)) { $pio = (Get-Command platformio -ErrorAction Stop).Source }
  $env:PYTHONUTF8 = '1'
  $env:PYTHONIOENCODING = 'utf-8'
  Push-Location $source
  try {
    Invoke-Checked npm.cmd @('ci')
    Invoke-Checked npm.cmd @('test')
    Invoke-Checked npm.cmd @('run', 'build')
    Invoke-Checked $pio @('run', '-e', 'bc250_power')
    $firmware = Join-Path $run "BC250-$Tag.bin"
    Copy-Item '.pio/build/bc250_power/firmware.bin' $firmware
    $manifest.status = 'built'
    $manifest['firmwareSha256'] = (Get-FileHash $firmware -Algorithm SHA256).Hash
    $manifest | ConvertTo-Json -Depth 5 | Set-Content -Encoding UTF8 $manifestPath
    Write-Host "Firmware: $firmware"
  } finally { Pop-Location }
} finally { Pop-Location }
# AI: end
